MOD = 10 ** 9 + 7
MAXN = 3 * 10 ** 5

def modpow(base, exp, mod):
	result = 1
	while exp:
		if exp & 1:
			result = result * base % mod
		base = base * base % mod
		exp >>= 1
	return result

def modinv(base, mod):
	return modpow(base, mod - 2, mod)
FACT = [1] * (MAXN + 1)
FACTINV = [1] * (MAXN + 1)
POW2 = [1] * (MAXN + 1)
POW2_1INV = [1] * (MAXN + 1)
for n in range(1, MAXN + 1):
	FACT[n] = n * FACT[n - 1] % MOD
	FACTINV[n] = modinv(FACT[n], MOD)
	POW2[n] = 2 * POW2[n - 1] % MOD
	POW2_1INV[n] = modinv(POW2[n] - 1, MOD)

def binomial(N, K):
	return FACT[N] * FACTINV[K] * FACTINV[N - K]

def main(N):
	expect = 0
	for K in range(1, N + 1):
		expect = (expect - (-1) ** K * binomial(N, K) * POW2[K] * POW2_1INV[K]) % MOD
	return expect
T = int(input().strip())
for _ in range(T):
	N = int(input().strip())
	print(main(N))
